# Wallpaper Engine — scene (.pkg) renderer + Workshop subscription source,
# plus the CEF web renderer when built with -DBUILD_WEWEB=ON.
#
# GENERATED by CMake (configure_file) — edit plugin.toml.in / the CMake
# rules, not the installed copy. Every plugin must ship a sibling
# `files.txt` (one path per line); this one is produced by CMake.
#
# The Lua entry advertises scene/video/web source and subscription capabilities;
# video routes to the image/video plugin's renderer purely by wallpaper type.

[plugin]
id = "org.waywallen.open-wallpaper-engine"
name = "Wallpaper Engine"
version = "0.2.0"
update = "https://github.com/waywallen/open-wallpaper-engine/raw/refs/heads/main/update.json"
entry = "main.lua"
entry_version = 3

[renderers.wescene-renderer]
bin = "bin/waywallen-wescene-renderer"
types = ["scene"]
priority = 100
spawn_version = 8
extras = ["assets", "workshop_id"]

[renderers.wescene-renderer.settings]
enable_audio = { type = "bool", default = true, identity = false, label_key = "settings.wescene.enable_audio", group = "audio", order = 5 }
volume = { type = "u32", default = 100, min = 0, max = 100, step = 1, identity = false, label_key = "settings.wescene.volume", group = "audio", order = 10 }
fps    = { type = "u32", default = 30,  min = 1, max = 240, step = 1, identity = false, label_key = "settings.wescene.fps", group = "render", order = 20 }
hwdec = { type = "string", default = "auto", choices = ["auto", "vaapi", "vulkan", "none"], identity = true, label_key = "settings.wescene.hwdec", group = "decode", order = 20 }
render_node = { type = "string", default = "", identity = true, label_key = "settings.wescene.render_node", group = "render", order = 30 }
msaa   = { type = "u32", default = 1, min = 1, max = 16, step = 1, identity = true, label_key = "settings.wescene.msaa", group = "render", order = 25 }
# -1 = custom, 1 = 720p, 2 = 1080p, 3 = 1440p, 4 = 2160p. Origin is disallowed for scene.
resolution = { type = "i32", default = 2, min = -1, max = 4, step = 1, identity = true, label_key = "settings.wescene.resolution", group = "render", order = 22 }
custom_extent = { type = "u32", default = 1080, min = 1, max = 8192, step = 1, identity = true, label_key = "settings.wescene.custom_extent", group = "render", order = 23 }

# CEF (Wallpaper Engine *web*) renderer. web wp_type entries come from the
# Lua entry above.
[renderers.weweb-renderer]
bin = "bin/weweb/waywallen-weweb-renderer"
types = ["web"]
priority = 100
spawn_version = 8
extras = ["workshop_id"]

[renderers.weweb-renderer.settings]
enable_audio = { type = "bool", default = true, identity = true, label_key = "settings.weweb.enable_audio", group = "audio", order = 5 }
volume = { type = "u32", default = 100, min = 0, max = 100, step = 1, identity = false, label_key = "settings.weweb.volume", group = "audio", order = 10 }
# Hot-reloadable via SetWindowlessFrameRate on the live browser.
fps = { type = "u32", default = 30, min = 1, max = 240, step = 1, identity = false, label_key = "settings.weweb.fps", group = "render", order = 20 }
# 1 = 720p, 2 = 1080p, 3 = 1440p, 4 = 2160p. Origin/custom are disallowed for web.
resolution = { type = "i32", default = 2, min = 1, max = 4, step = 1, identity = true, label_key = "settings.weweb.resolution", group = "render", order = 25 }
shared_texture_enabled = { type = "bool", default = true, identity = true, label_key = "settings.weweb.shared_texture_enabled", group = "render", order = 30 }
render_node = { type = "string", default = "", identity = true, label_key = "settings.weweb.render_node", group = "render", order = 35 }
# CEF can only honour --remote-debugging-port at CefInitialize time;
# changing it requires a respawn — identity = true.
remote_debugging_port = { type = "u32", default = 0, min = 0, max = 65535, identity = true, label_key = "settings.weweb.remote_debugging_port", group = "debug", order = 40 }
